"use client";

import { Formik, Form, Field, ErrorMessage } from "formik";
import * as Yup from "yup";
import { useMutation } from "@tanstack/react-query";
import { toast } from "react-toastify";
import Select from "react-select";
import { Product, Category } from "@/types/product";
import { updateProduct } from "@/components/product/api";

interface ProductFormProps {
  initialValues: Partial<Product>;
  categories: Category[];
  productId: string;
}

interface SelectOption {
  value: number;
  label: string;
}

const ProductForm = ({ initialValues, categories, productId }: ProductFormProps) => {
  const mutation = useMutation({
    mutationFn: (values: Partial<Product>) => updateProduct({ productId, values }),
    onSuccess: () => toast.success("Product updated successfully!"),
    onError: (error) => {
      toast.error("Failed to update product.");
      console.error(error);
    },
  });

  return (
    <Formik
      enableReinitialize
      initialValues={initialValues}
      validationSchema={Yup.object({
        productName: Yup.string().min(3, "Product name must be at least 3 characters long").required("Required"),
        detail: Yup.string().min(3, "Details must be at least 3 characters long").required("Required"),
        price: Yup.number().typeError("Price must be a number").positive("Price must be a positive number").required("Required"),
        weight: Yup.number().typeError("Weight must be a number").positive("Weight must be a positive number").required("Required"),
        productCategory: Yup.string().required("Category is required"),
      })}
      onSubmit={(values) => {
        const formattedValues = {
          ...values,
          categoryId: values.productCategory ? Number(values.productCategory) : undefined,
        };
        delete formattedValues.productCategory;
        console.log("Sending data to API:", formattedValues);
        mutation.mutate(formattedValues);
      }}
    >
      
      {({ values, setFieldValue, isSubmitting }) => {
          console.log("Current Formik values:", values); // Logs all Formik values
          return (
            <Form className="space-y-4">
              <div>
                <label className="block text-gray-500">Product Name</label>
                <Field type="text" name="productName" className="border p-2 rounded w-full" />
                <ErrorMessage name="productName" component="div" className="text-red-500" />
              </div>

              <div>
                <label className="block text-gray-500">Details</label>
                <Field type="text" name="detail" className="border p-2 rounded w-full" />
                <ErrorMessage name="detail" component="div" className="text-red-500" />
              </div>

              <div>
                <label className="block text-gray-500">Price (Rp.)</label>
                <Field type="number" name="price" className="border p-2 rounded w-full" />
                <ErrorMessage name="price" component="div" className="text-red-500" />
              </div>

              <div>
                <label className="block text-gray-500">Weight</label>
                <Field type="number" name="weight" className="border p-2 rounded w-full" />
                <ErrorMessage name="weight" component="div" className="text-red-500" />
              </div>

              <div>
                <label className="block text-gray-500">Product Category</label>
                <Select
                  options={categories?.map((category) => ({
                    value: category.categoryId, 
                    label: category.categoryName 
                  }))}
                  value={
                    categories
                      ?.map((category) => ({ value: category.categoryId, label: category.categoryName }))
                      .find((option) => option.value === Number(values.productCategory)) || null
                  }

                  onChange={(selectedOption: SelectOption | null) => 
                    setFieldValue("productCategory", selectedOption?.value || "")
                  }

                  className="border p-2 rounded w-full text-gray-500"
                  placeholder="Search category..."
                />
                <ErrorMessage name="productCategory" component="div" className="text-red-500" />
              </div>

              <button type="submit" disabled={isSubmitting || mutation.isPending}>
                {mutation.isPending ? "Updating..." : "Update Product"}
              </button>
            </Form>
          );
        }}
    </Formik>
  );
};

export default ProductForm;